(function(){
  var f=document.querySelector("form.write-article input[name=user_code]");
  if(!f) return "NO_FIELD";
  var setter=Object.getOwnPropertyDescriptor(HTMLInputElement.prototype,"value").set;
  setter.call(f,"9762197");
  f.dispatchEvent(new Event("change",{bubbles:true}));
  var card=document.querySelector(".write-submit-card");
  var visible=card&&getComputedStyle(card).display!=="none";
  if(!visible){
    var b=Array.from(document.querySelectorAll("[class*=submit]")).find(function(e){return (e.textContent||"").trim().indexOf("发布文章")>=0});
    b.click();
  }
  var btn=Array.from(document.querySelectorAll(".write-submit-card [class*=submit],.write-submit-card button")).find(function(e){return (e.textContent||"").trim().indexOf("确认并发布")>=0});
  if(!btn) return "NO_CONFIRM";
  btn.click();
  return "RETRY_PUBLISH";
})()
